def _check_lane(self, section: Int, lane: Int) raises:
    if section < 0 or section >= len(self.sections):
        raise Error("The road has no section at that index")
    if lane < 0 or lane >= len(self.sections[section].lanes):
        raise Error("The section has no lane at that index")

def _rounded_axis_lane_minimum(
    road: Road,
    section: Int,
    lane: Int,
    low: Float64,
    high: Float64,
    location: Vector3,
    mut nodes: Int,
    mut terms: Int,
    max_nodes: Int,
    max_terms: Int,
    max_depth: Int,
) raises -> Optional[Tuple[Float64, Float64, Array[Float64, 3], Int, Int]]:
    # The old axis eligibility scan is already charged by the map. This
    # optional context has its own node and reference term, including when
    # it declines. Pass those counters into ordinary fallback unchanged.
    if len(road.info.geometries) != 1:
        return None
    if road.info.geometries[0].geometry.kind != LINE:
        return None
    if nodes >= max_nodes:
        raise Error("Lane refinement exhausted its interval work limit")
    nodes += 1
    if terms > max_terms - 1:
        raise Error("Lane refinement exhausted its quadrature work limit")
    terms += 1
    var context = _rounded_line_axis_context(road, section, lane, low, high)
    if not context:
        return None
    # Reserve the search root separately from the optional proof node.
    if nodes >= max_nodes:
        raise Error("Lane refinement exhausted its interval work limit")
    nodes += 1
    var depth = 0
    var model = context.value()
    var axis = model.axis
    var direction = Float64(1.0 if model.slope > 0.0 else -1.0)
    var query: Array[Float64, 3] = [
        Float64(location.x),
        Float64(location.y),
        Float64(location.z),
    ]
    _finite_point(query)
    var lo = Float64(0.0) if low == 0.0 else low
    var hi = high
    var left = _checked_center(road, section, lane, lo, terms, max_terms)
    var right = _checked_center(road, section, lane, hi, terms, max_terms)
    var target = direction * query[axis]
    if target <= direction * left[axis] or lo == hi:
        return (lo, _legacy_square(left, query), left^, nodes, terms)
    if target >= direction * right[axis]:
        return (hi, _legacy_square(right, query), right^, nodes, terms)
    # An inverse is a seed only. A hit of the actual stored coordinate is
    # the exact minimum because the proof fixes both other coordinates.
    var seed = lo + (query[axis] - left[axis]) / model.slope
    if isfinite(seed):
        seed = min(max(seed, lo), hi)
        var point = _checked_center(road, section, lane, seed, terms, max_terms)
        if point[axis] == query[axis]:
            return (seed, _legacy_square(point, query), point^, nodes, terms)
        if direction * point[axis] < target:
            lo = seed
            left = point^
        else:
            hi = seed
            right = point^
    var lo_bits = bitcast[DType.uint64](lo)
    var hi_bits = bitcast[DType.uint64](hi)
    while hi_bits - lo_bits > UInt64(1):
        if nodes >= max_nodes:
            raise Error("Lane refinement exhausted its interval work limit")
        if depth >= max_depth:
            raise Error(
                "Lane refinement exhausted its numerical accuracy limit"
            )
        nodes += 1
        depth += 1
        var middle_bits = lo_bits + (hi_bits - lo_bits) // UInt64(2)
        var middle = bitcast[DType.float64](middle_bits)
        var point = _checked_center(
            road, section, lane, middle, terms, max_terms
        )
        if point[axis] == query[axis]:
            return (middle, _legacy_square(point, query), point^, nodes, terms)
        if direction * point[axis] < target:
            lo_bits = middle_bits
            lo = middle
            left = point^
        else:
            hi_bits = middle_bits
            hi = middle
            right = point^
    # Parameters outside the adjacent bracket have no smaller axis residual.
    # Compare full distances exactly and keep the lower s on an exact tie.
    if _wide_point_order(right, left, query) < 0:
        return (hi, _legacy_square(right, query), right^, nodes, terms)
    return (lo, _legacy_square(left, query), left^, nodes, terms)

def _reference_rounded_line_axis_context(
    road: Road, section: Int, lane: Int, low: Float64, high: Float64
) raises -> Optional[_RoundedLineAxis]:
    road._check_lane(section, lane)
    if len(road.info.geometries) != 1:
        return None
    ref record = road.info.geometries[0]
    if record.geometry.kind != LINE:
        return None
    if (
        not _RoundedBox.bounds(low, high).known
        or low < 0.0
        or high > road.length
    ):
        return None
    # One record active at low also covers high: the domain is ordered.
    if info_index(road.info.geometries, low) != 0:
        return None
    var offset_at = info_index(road.info.lane_offsets, low)
    var elevation_at = info_index(road.info.elevations, low)
    if (
        offset_at < 0
        or elevation_at < 0
        or info_index(road.info.lane_offsets, high) != offset_at
        or info_index(road.info.elevations, high) != elevation_at
    ):
        return None
    var lane_offset = _rounded_constant(
        road.info.lane_offsets[offset_at].polynomial
    )
    var elevation = _rounded_constant(
        road.info.elevations[elevation_at].polynomial
    )
    if not lane_offset.known or not elevation.known:
        return None
    ref lanes = road.sections[section].lanes
    var id = lanes[lane].id
    var offset = _RoundedBox.point(0.0)
    if id.value != 0:
        var negative = id.value < 0
        var sign = _RoundedBox.point(1.0 if negative else -1.0)
        for position in range(len(lanes)):
            var i = len(lanes) - 1 - position if negative else position
            if negative:
                if lanes[i].id.value >= 0:
                    continue
            elif lanes[i].id.value < 1:
                continue
            ref widths = lanes[i].info.widths
            var width_at = info_index(widths, low)
            if width_at < 0 or info_index(widths, high) != width_at:
                return None
            var width = _rounded_constant(widths[width_at].polynomial)
            if not width.known:
                return None
            var contribution = sign * width
            if lanes[i].id == id:
                contribution = contribution * _RoundedBox.point(0.5)
            offset = offset + contribution
            if not offset.known:
                return None
            if lanes[i].id == id:
                break
    offset = offset - lane_offset
    if not offset.known or offset.low != offset.high:
        return None
    var start = _RoundedBox.point(record.s)
    var d = _RoundedBox.bounds(low, high) - start
    var length = record.geometry.length
    if not d.known or not _rounded_operand(length) or length < 0.0:
        return None
    d = _RoundedBox.bounds(
        min(max(d.low, 0.0), length), min(max(d.high, 0.0), length)
    )
    if not d.known:
        return None
    # These are the canonical no-inline scalar trig graph's stored outputs.
    # Never substitute ideal sine/cosine or snap a near-axis heading.
    var cosine = _RoundedBox.point(_curve_cos(record.geometry.heading))
    var sine = _RoundedBox.point(_curve_sin(record.geometry.heading))
    var x = _rounded_madd(d, cosine, _RoundedBox.point(record.geometry.x))
    var y = _rounded_madd(d, sine, _RoundedBox.point(record.geometry.y))
    x = _rounded_madd(offset, sine, x)
    y = -_rounded_madd(-offset, cosine, y)
    if not (x.known and y.known and elevation.low == elevation.high):
        return None
    # Subtraction, clamp, constant multiply, rounded addition/FMA, and final
    # sign reversal compose monotonically. Each permitted contraction graph
    # has the indicated direction. The other two stored coordinates must be
    # singleton boxes under every permitted graph over this original domain.
    if y.low == y.high and cosine.low != 0.0:
        return _RoundedLineAxis(0, cosine.low)
    if x.low == x.high and sine.low != 0.0:
        return _RoundedLineAxis(1, -sine.low)
    return None
